// Colors for the mandala
const colors = [
  '#ffd5b7', // pastel pink
  '#c9e9ff', // pastel blue
  '#d0f4de', // pastel green
  '#fff9b7', // pastel yellow
  '#e6c5ff', // pastel purple
  '#ffb3c6'  // pastel rose
];

// Draw circles with different shades
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 30;
  const context = ctx.createRadialGradient(
    centerX, centerY,
    radius - 20,
    centerX, centerY,
    radius + 20
  );

  const gradientColors = [];
  for (let j = 0; j < 3; j++) {
    gradientColors.push(colors[i]);
    gradientColors.push('#ffffff');
    gradientColors.push('#ffffff');
  }

  context.addColorStop(0, gradientColors[0]);
  context.addColorStop(0.33, gradientColors[1]);
  context.addColorStop(0.66, gradientColors[2]);
  context.addColorStop(1, gradientColors[3]);

  ctx.fillStyle = context;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fill();
}

// Draw radial lines
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 2;
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const x1 = centerX + Math.cos(angle) * (maxRadius - 10);
  const y1 = centerY + Math.sin(angle) * (maxRadius - 10);
  const x2 = centerX + Math.cos(angle) * maxRadius;
  const y2 = centerY + Math.sin(angle) * maxRadius;

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
}

// Draw triangles
ctx.fillStyle = '#ff6b7a';
for (let i = 0; i < 12; i++) {
  const angle1 = (i / 12) * Math.PI * 2;
  const angle2 = ((i + 1) / 12) * Math.PI * 2;
  const angle3 = ((i + 2) / 12) * Math.PI * 2;

  const x1 = centerX + Math.cos(angle1) * (maxRadius - 30);
  const y1 = centerY + Math.sin(angle1) * (maxRadius - 30);
  const x2 = centerX + Math.cos(angle2) * (maxRadius - 30);
  const y2 = centerY + Math.sin(angle2) * (maxRadius - 30);
  const x3 = centerX + Math.cos(angle3) * (maxRadius - 30);
  const y3 = centerY + Math.sin(angle3) * (maxRadius - 30);

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.lineTo(x3, y3);
  ctx.closePath();
  ctx.fill();
}

