// Cool tones palette for a fractal spiral
const SKY = '#0c1445';
const GROUND = '#1a2a5e';
const ACCENT = '#4a90e2';
const SHADOW = '#0a1929';
const HIGHLIGHT = '#8ab4f8';

// Draw background
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw spiral with cool tones
function drawSpiral(x, y, size, depth) {
    if (depth > 0) {
        // Draw spiral arms
        ctx.fillStyle = ACCENT;
        ctx.globalAlpha = 0.7;
        ctx.fillRect(x - size, y - size, size * 2, size * 2);

        // Draw inner spiral arms
        ctx.fillStyle = SHADOW;
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x - size/2, y - size/2, size, size);

        // Recursive call for next arm
        drawSpiral(x + size/2, y + size/2, size * 0.8, depth - 1);
        drawSpiral(x - size/2, y + size/2, size * 0.8, depth - 1);
        drawSpiral(x + size/2, y - size/2, size * 0.8, depth - 1);
        drawSpiral(x - size/2, y - size/2, size * 0.8, depth - 1);
    }
}

