for(let i = 0; i < 20; i++) {
    let angle = i * 0.3;
    let x = 200 + Math.cos(angle) * r;
    let y = 250 + Math.sin(angle) * r;
    if(i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    r += 5;
}
ctx.closePath();
ctx.fill();

